create temporary view item_category_${grass_region_without_quote} as
select
    item_id
    ,level1_global_be_category_id
    ,level1_global_be_category
from
    srdi_mart.dim_sr_data_warehouse_item
where
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and level1_global_be_category_id in (100011, 100017)
        -- 100011: Men Clothes, 100017: Women Clothes
    and item_id > 0
;

--sql_divide_splitter--
create temporary view dwm_user_item_${grass_region_without_quote} as
select
    user_id
    ,item_id
    ,operation
from
    srdi_mart.dwm_sr_data_warehouse_platform_user_item
where
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and operation in ('cart','order')
;

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_platform_user_item_category_1d
partition (grass_region = ${grass_region}, local_date = ${local_date}, operation)
select
    user_id
    ,t1.item_id
    ,max(level1_global_be_category_id) as level1_global_be_category_id
    ,max(level1_global_be_category) as level1_global_be_category
    ,operation
from
    dwm_user_item_${grass_region_without_quote} as t1
inner join
    item_category_${grass_region_without_quote} as t2
on
    t1.item_id = t2.item_id
group by user_id, t1.item_id, operation
;
